import{_ as e}from"./chunks/field-pt.C7x8tUka.js";import{_ as o}from"./chunks/table-pt.H2FavDxQ.js";import{_ as r,o as t,c as s,a2 as d}from"./chunks/framework.DHtetOlu.js";const v=JSON.parse('{"title":"Resultados","description":"","frontmatter":{},"headers":[],"relativePath":"guide/results.md","filePath":"guide/results.md"}'),i={name:"guide/results.md"};function n(l,a,c,m,u,p){return t(),s("div",null,[...a[0]||(a[0]=[d('<h1 id="resultados" tabindex="-1">Resultados <a class="header-anchor" href="#resultados" aria-label="Permalink to &quot;Resultados&quot;">​</a></h1><p>Depois de resolver, a física aparece em <strong>Resultados</strong> com o |B| máximo. O <code>+</code> dela cria vistas, gráficos e tabelas; cada um abre como uma <strong>aba</strong> no canvas (a aba <strong>Desenho</strong> continua lá).</p><h2 id="vistas-de-campo" tabindex="-1">Vistas de campo <a class="header-anchor" href="#vistas-de-campo" aria-label="Permalink to &quot;Vistas de campo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>O que mostra</th></tr></thead><tbody><tr><td>Mapa de campo</td><td>superfície colorida (</td></tr><tr><td>Mapa interpolado</td><td>o mesmo com interpolação de alta ordem e subdivisão: contornos suaves</td></tr><tr><td>Gráfico sobre linha</td><td>uma grandeza ao longo de uma curva do desenho (B, Bn, Bt, H, A…)</td></tr></tbody></table><p>Uma vista tem <strong>camadas</strong> (superfície, contorno, setas), que podem ser ocultadas, duplicadas e arrastadas na árvore para outra vista. Nas propriedades da camada: grandeza, faixa de valores, número de linhas, mapa de cores, cor e espaçamento das setas.</p><ul><li>Clique na <strong>legenda</strong> para mudar os limites; arraste para mover e use a alça do canto para redimensionar.</li><li><strong>Exportar</strong> (barra superior) gera PNG ou JPG da vista.</li></ul><p><img src="'+e+'" alt="Mapa de |B| com linhas de fluxo" class="shot"></p><h2 id="tabelas-e-variaveis-de-resultado" tabindex="-1">Tabelas e variáveis de resultado <a class="header-anchor" href="#tabelas-e-variaveis-de-resultado" aria-label="Permalink to &quot;Tabelas e variáveis de resultado&quot;">​</a></h2><p>Uma <strong>Tabela</strong> reúne itens, e cada item gera <strong>variáveis de resultado</strong> com nome, que podem ser lidas por scripts (<code>r.result(&quot;nome&quot;)</code>).</p><table tabindex="0"><thead><tr><th>Item</th><th>Resultados</th></tr></thead><tbody><tr><td>Circuitos</td><td>corrente, espiras, fluxo concatenado λ, L = λ/I, R CC, V CC e perdas I²R de cada circuito</td></tr><tr><td>Integral de superfície</td><td>nas regiões escolhidas: área, volume, ∫A, corrente, energia, B médio, perdas (Joule e ferro), <strong>força Fx, Fy e torque</strong></td></tr><tr><td>Integral sobre linha</td><td>sobre uma curva: comprimento, fluxo Φ, força magnetomotriz ∫H·dl, ∫B, B médio, <strong>força e torque</strong> (contorno fechado)</td></tr><tr><td>Fórmula</td><td>uma expressão sobre as outras variáveis (por exemplo <code>0.5*Bobina_L*Bobina_I^2</code>)</td></tr></tbody></table><p>Cada saída tem um nome editável (o padrão é o prefixo do item mais a grandeza, como <code>S1_fx</code>). As variáveis de circuito se chamam <code>&lt;circuito&gt;_I</code>, <code>&lt;circuito&gt;_lambda</code>, <code>&lt;circuito&gt;_L</code> e <code>&lt;circuito&gt;_R</code>.</p><p><img src="'+o+'" alt="Tabela de circuitos" class="shot"></p><h2 id="forca-e-torque" tabindex="-1">Força e torque <a class="header-anchor" href="#forca-e-torque" aria-label="Permalink to &quot;Força e torque&quot;">​</a></h2><p>A força é calculada pelo <strong>tensor de Maxwell</strong>, de dois jeitos:</p><ul><li><strong>Integral de superfície</strong> (recomendada): selecione as regiões do corpo. Usa o tensor ponderado, como o <em>block integral</em> do FEMM, e só os elementos de ar em volta do corpo contribuem. É a mais precisa.</li><li><strong>Integral sobre linha</strong>: um contorno fechado no ar em volta do corpo.</li></ul><p>O torque é em torno da origem. No plano, os valores já incluem a profundidade.</p><h2 id="transitorio-e-ac" tabindex="-1">Transitório e AC <a class="header-anchor" href="#transitorio-e-ac" aria-label="Permalink to &quot;Transitório e AC&quot;">​</a></h2><p>Na análise transitória e na AC, a barra da vista tem uma <strong>barra de tempo</strong>, ▶ para animar, quadros por segundo e <strong>Exportar animação (WebM)</strong>. Os itens de tabela viram <strong>curvas no tempo</strong>; nas propriedades do item dá para ver a tabela num instante escolhido. Os sinais de um circuito externo aparecem ao clicar num componente.</p><h2 id="exportar" tabindex="-1">Exportar <a class="header-anchor" href="#exportar" aria-label="Permalink to &quot;Exportar&quot;">​</a></h2><p>O botão <strong>Exportar</strong> da barra superior exporta a aba ativa: vista de campo em PNG ou JPG, gráfico em SVG, PNG, JPG ou CSV, e tabela em CSV. A animação (WebM) sai pela barra da vista. Veja <a href="./files.html#exportar">Arquivos, importar e exportar</a>.</p>',20)])])}const f=r(i,[["render",n]]);export{v as __pageData,f as default};
